import React, { useEffect, useState } from 'react'
import {
  ResponsiveContainer,
  PieChart, Pie, Cell,
  BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid
} from 'recharts'
import { loadDashboardData } from '../api/dashboard'

const RISK_COLORS = {
  safe:    '#60a5fa',
  warning: '#facc15',
  danger:  '#ef4444',
}

const VULN_COLORS = {
  low:    '#10b981',
  medium: '#f59e0b',
  high:   '#ef4444',
}

export default function DashboardPage() {
  const [data, setData]     = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError]     = useState('')

  useEffect(() => {
    (async () => {
      setLoading(true)
      try {
        const d = await loadDashboardData()
        setData(d)
      } catch (e) {
        console.error(e)
        setError(e.message)
      } finally {
        setLoading(false)
      }
    })()
  }, [])

  if (loading) return <p className="text-center py-8">불러오는 중…</p>
  if (error)   return <p className="text-red-500 text-center py-8">{error}</p>

  const { summary, riskCounts, vulnCounts } = data

  // PieChart 용 배열로 변환
  const riskPieData = Object.entries(riskCounts)
    .map(([k,v]) => ({ name: k, value: v }))
    .filter(x => x.value > 0)

  const vulnPieData = Object.entries(vulnCounts)
    .map(([k,v]) => ({ name: k, value: v }))
    .filter(x => x.value > 0)

  return (
    <main className="max-w-5xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6">포트스캐너 대시보드</h1>

      {/* 요약 카드 */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
        <div className="p-4 bg-white shadow rounded">
          <h2 className="text-sm text-gray-500">전체 자산 수</h2>
          <p className="text-3xl font-semibold">{summary.total_assets}</p>
        </div>
        <div className="p-4 bg-white shadow rounded">
          <h2 className="text-sm text-gray-500">위험 자산 수</h2>
          <p className="text-3xl font-semibold">{summary.risky_assets}</p>
        </div>
        <div className="p-4 bg-white shadow rounded">
          <h2 className="text-sm text-gray-500">Critical CVE 건수</h2>
          <p className="text-3xl font-semibold">{summary.critical_cves}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* 위험도 분포 Pie */}
        <div className="p-4 bg-white shadow rounded">
          <h3 className="text-lg mb-2">위험도 분포</h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={riskPieData}
                dataKey="value"
                nameKey="name"
                outerRadius={80}
                label={(entry) => `${entry.name}: ${entry.value}`}
              >
                {riskPieData.map((entry, idx) => (
                  <Cell key={idx} fill={RISK_COLORS[entry.name]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* 취약점 심각도 분포 Pie */}
        <div className="p-4 bg-white shadow rounded">
          <h3 className="text-lg mb-2">취약점 심각도 분포</h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={vulnPieData}
                dataKey="value"
                nameKey="name"
                outerRadius={80}
                label={(entry) => `${entry.name}: ${entry.value}`}
              >
                {vulnPieData.map((entry, idx) => (
                  <Cell key={idx} fill={VULN_COLORS[entry.name]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 자산별 열린 포트 수 BarChart (예시) */}
      <div className="mt-8 p-4 bg-white shadow rounded">
        <h3 className="text-lg mb-2">자산별 열린 포트 수</h3>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart
            data={summary.assets.map(a => ({
              name: a.name,
              openPorts: a.ports_count
            }))}
            margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
          >
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="name" />
            <YAxis allowDecimals={false} />
            <Tooltip />
            <Bar dataKey="openPorts" fill="#3b82f6" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </main>
  )
}
